  'Source checks use HTTP GET. Unchanged automatic runs skip the agent. An optional JSON pointer watches only that value and ignores object key order. Manual tests always run. Quiet hours defer successful Bot reports. Failures and approvals stay visible. Usage limits can overrun when reports arrive late.':
    'सोर्स जाँच में HTTP GET का उपयोग होता है। बिना बदलाव वाले स्वचालित रन एजेंट को छोड़ देते हैं। वैकल्पिक JSON pointer केवल उस मान पर नज़र रखता है और ऑब्जेक्ट की कुंजियों के क्रम को अनदेखा करता है। मैन्युअल टेस्ट हमेशा चलते हैं। शांत समय के दौरान सफल Bot रिपोर्ट देर से भेजी जाती हैं। विफलताएँ और अनुमोदन दिखते रहते हैं। रिपोर्ट देर से आने पर उपयोग की सीमाएँ पार हो सकती हैं।',
