  'Connect a computer to configure its settings.': 'इसकी सेटिंग कॉन्फ़िगर करने के लिए कंप्यूटर कनेक्ट करें।',
  'Dictation on the selected computer': 'चुने गए कंप्यूटर पर डिक्टेशन',
  'Off by default on each device. Finished recordings go only to the thread’s computer. No cloud fallback. The computer needs FFmpeg to read phone recordings. Update the phone app to enable recording.':
    'हर डिवाइस पर डिफ़ॉल्ट रूप से बंद। रिकॉर्डिंग पूरी होने पर सिर्फ़ थ्रेड के कंप्यूटर पर भेजी जाती है। कोई क्लाउड बैकअप नहीं। फ़ोन की रिकॉर्डिंग पढ़ने के लिए कंप्यूटर पर FFmpeg चाहिए। रिकॉर्डिंग चालू करने के लिए फ़ोन ऐप अपडेट करें।',
