  'Your sharing key is saved with your account. Signing in restores access even if every device is lost. Connect can recover this key. A manual backup is optional.':
    'आपकी साझाकरण कुंजी आपके खाते में सेव है। सभी डिवाइस खो जाने पर भी साइन इन करके ऐक्सेस बहाल किया जा सकता है। Connect इस कुंजी को पुनः प्राप्त कर सकता है। मैन्युअल बैकअप वैकल्पिक है।',
