    'चुने गए कंप्यूटर पर इस प्रोजेक्ट का सेशन प्रीव्यू करें। Dovo जारी रखने के लिए एक निजी कॉपी बनाता है और टर्मिनल सोर्स को जस का तस छोड़ता है। जब तक आप पूरा एक्सेस न चुनें, Pi टूल बंद रहेंगे; एक्सटेंशन और MCP भी बंद रहेंगे। जारी रखने के लिए @earendil-works/pi-coding-agent 1.4 या नया संस्करण चाहिए।',
