  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'इस रनटाइम होस्ट पर CuaDriver सेट अप करें। CuaDriver OS अनुमतियाँ संभालता है; Dovo MCP के ज़रिए एजेंट कनेक्ट करता है।',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'होस्ट के एक्ज़ीक्यूटेबल नाम या पाथ, बिना shell quoting के। एजेंट ओवरराइड को प्राथमिकता मिलती है। नए टर्मिनल इन shell सेटिंग का उपयोग करते हैं।',
