    'कंप्यूटर ऐक्सेस बदल गया है। यह कार्रवाई शायद पहले ही हो चुकी हो; फिर से आज़माने पर यह दोबारा हो सकती है। आगे बढ़ने से पहले कंप्यूटर जाँचें।',
