  'Attach saved file?': 'सहेजी गई फ़ाइल जोड़ें?',
  'This adds the saved file to the current draft of its original task. It does not modify a queued message.':
    'इससे सहेजी गई फ़ाइल अपने मूल टास्क के मौजूदा ड्राफ़्ट में जुड़ जाएगी। इससे कतार में मौजूद मैसेज नहीं बदलेगा।',
  Attach: 'जोड़ें',
  'Discard saved upload': 'सहेजा गया अपलोड छोड़ें',
  'Discard saved upload?': 'सहेजा गया अपलोड छोड़ें?',
  'This permanently abandons this upload. An attachment already saved in a message or draft is not removed.':
    'इससे यह अपलोड हमेशा के लिए छोड़ दिया जाएगा। मैसेज या ड्राफ़्ट में पहले से सहेजा गया अटैचमेंट नहीं हटेगा।',
  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'फिर से पेयर करें',
  'Connection stages': 'कनेक्शन के चरण',
  'Start your computer': 'कंप्यूटर चालू करें',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'अपने कंप्यूटर पर Dovo खोलें और उसे चालू रखें। Settings → Devices & runtime में साइन इन करें और Dovo Connect चालू करें। अपने फ़ोन पर भी उसी अकाउंट में साइन इन करें और Connect चुनें। इंटरनेट ऐक्सेस के लिए पेयरिंग कोड, VPN या स्थानीय IP की ज़रूरत नहीं।',
  'Direct internet connection': 'सीधा इंटरनेट कनेक्शन',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN आपके फ़ोन को सीधे कंप्यूटर से कनेक्ट करता है। आपकी सामग्री एंड-टू-एंड एन्क्रिप्टेड है। Dovo Connect चालू करने से, नेटवर्क द्वारा सीधे कनेक्शन रोकने पर एन्क्रिप्टेड रिले फ़ॉलबैक की अनुमति मिलती है। रिले एन्क्रिप्टेड ट्रैफ़िक आगे भेजता है; वह आपकी सामग्री पढ़ नहीं सकता।',
  'LAN / VPN connections': 'LAN / VPN कनेक्शन',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'उपलब्ध होने पर इस कनेक्शन को प्राथमिकता देने के लिए LAN / VPN को अलग से पेयर करें। कंप्यूटर पर दिखाया गया पूरा Wi-Fi, Tailscale, NetBird या HTTPS पता, पोर्ट समेत कॉपी करें। localhost और 0.0.0.0 ऐसे पते नहीं हैं जिनसे आपका फ़ोन कनेक्ट कर सके।',
  'Check your network': 'अपना नेटवर्क जाँचें',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'एक ही Wi-Fi इस्तेमाल करें या दोनों डिवाइस को अपने VPN से कनेक्ट करें। Wi-Fi कनेक्शन के लिए, iPhone Settings में Dovo को अपने स्थानीय नेटवर्क का ऐक्सेस दें।',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'पेयरिंग कोड दो मिनट बाद समाप्त हो जाते हैं। CLI कोड अपने-आप अनुमति दे देते हैं; डेस्कटॉप से मिले कोड के लिए वहाँ अनुमति देना ज़रूरी हो सकता है।',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'आपकी पेयरिंग सहेज ली गई है। दूसरा कोड बनाने से पहले Reconnect आज़माएँ। अगर पता बदल गया है, तो इस कंप्यूटर की सेटिंग में Update connection address चुनें।',
